/**
 * The input of the Gland Quantity, Cable Lug Quantity and Drum Schedule generators: the Cable Schedule last generated by
 * the Cable Schedule Generator for this user and the selected project. The workbook stays on the server; the page only
 * shows its name and status and sends its id with every calculation (a newer schedule makes the server refuse an old id,
 * so a result is never labelled with the wrong workbook).
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import { AlertTriangle, CheckCircle2, FileSpreadsheet, RefreshCw } from 'lucide-react';
import api from '@/services/api';
import { getCurrentProject, subscribeProject } from '@/services/projectContext';
import Card from '../../ui/Card';

export interface GeneratedSchedule {
  available: boolean;
  message?: string;
  id?: string;
  filename?: string;
  generated_at?: string;
  project_id?: string | null;
  sheets?: string[];
  iodb_filename?: string;
  selected_jbs?: number | null;
}

export interface GeneratedScheduleState {
  gen: GeneratedSchedule | null;
  loading: boolean;
  error: string | null;
  refresh: () => void;
  /** Form fields naming the schedule for a calculation request (project + the schedule shown on screen). */
  fields: () => Record<string, string>;
}

/** Loaded once when the generator tab opens (switching tabs remounts it) and again when the project changes. */
export function useGeneratedSchedule(): GeneratedScheduleState {
  const [project, setProject] = useState(getCurrentProject());
  const [gen, setGen] = useState<GeneratedSchedule | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const seq = useRef(0);

  const refresh = useCallback(() => {
    const n = ++seq.current;                                   // only the latest answer is kept
    setLoading(true);
    api.get<GeneratedSchedule>('/cable-schedule/generated', { params: project ? { project_id: project } : {} })
      .then((r) => { if (n === seq.current) { setGen(r.data); setError(null); } })
      .catch((e) => { if (n === seq.current) { setGen(null); setError(e.response?.data?.detail || 'Could not check the generated Cable Schedule.'); } })
      .finally(() => { if (n === seq.current) setLoading(false); });
  }, [project]);

  useEffect(() => subscribeProject(setProject), []);
  useEffect(() => { refresh(); }, [refresh]);

  const fields = useCallback(() => {
    const f: Record<string, string> = {};
    if (project) f.project_id = project;
    if (gen?.id) f.generated_id = gen.id;
    return f;
  }, [project, gen?.id]);

  return { gen, loading, error, refresh, fields };
}

/** Read-only replacement of the old "upload a Cable Schedule" control. */
export default function GeneratedScheduleCard({ state, title = 'Input - Generated Cable Schedule', children }:
  { state: GeneratedScheduleState; title?: string; children?: React.ReactNode }) {
  const { gen, loading, error, refresh } = state;
  const ok = !!gen?.available;
  const row = (k: string, v: React.ReactNode) => (
    <div className="flex gap-2 text-sm"><span className="w-48 flex-shrink-0" style={{ color: 'var(--t1)' }}>{k}</span><span style={{ color: 'var(--t0)' }}>{v}</span></div>);
  return (
    <Card title={title} icon={FileSpreadsheet}
          actions={<button onClick={refresh} className="text-xs flex items-center gap-1 underline" style={{ color: 'var(--t1)' }} data-testid="generated-refresh">
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />Refresh</button>}>
      <div className="space-y-1.5" data-testid="generated-schedule">
        {row('Input Source', 'Cable Schedule Generator')}
        {row('Generated Cable Schedule', ok ? <span className="font-mono">{gen!.filename}</span> : '-')}
        {row('Status', loading && !gen ? 'Checking…' : ok
          ? <span className="text-green-600 font-semibold">Available</span>
          : <span className="text-red-500 font-semibold">Not Generated</span>)}
        {ok && <>
          {row('Generated', `${gen!.generated_at}${gen!.project_id ? ` · project ${gen!.project_id}` : ''}`)}
          {row('From IODB', `${gen!.iodb_filename}${gen!.selected_jbs ? ` · ${gen!.selected_jbs} selected junction box${gen!.selected_jbs === 1 ? '' : 'es'}` : ''}`)}
          {gen!.sheets && row('Sheets', gen!.sheets.join(' · '))}
          <p className="text-sm flex items-center gap-1.5 pt-1 text-green-600"><CheckCircle2 className="w-4 h-4" />
            The generated Cable Schedule has been loaded automatically. No upload is needed.</p>
        </>}
        {!ok && !loading && (
          <p className="text-sm flex items-start gap-1.5 pt-1 text-red-500"><AlertTriangle className="w-4 h-4 mt-0.5 flex-shrink-0" />
            {error || gen?.message || 'No generated Cable Schedule is available. Please generate a Cable Schedule using the Cable Schedule Generator first.'}</p>
        )}
        {children}
      </div>
    </Card>
  );
}

/** A calculation refused because a newer schedule exists (409) or none exists (404): reload the status and show why. */
export function handleSourceError(e: any, state: GeneratedScheduleState, setError: (m: string | null) => void, fallback: string) {
  const st = e?.response?.status;
  if (st === 409 || st === 404) state.refresh();
  setError(e?.response?.data?.detail || fallback);
}
